AssistantMessageToolRequest(name='create', tool_call_id='tooluse_KXBUp9KGM0nS2Q2bL9Ybhh', arguments={'file_text': '/* ============================================================
   Design Tokens
   ============================================================ */
:root {
  --color-brand-primary: #1a1a2e;
  --color-brand-accent: #e94560;
  --color-brand-accent-hover: #c73652;
  --color-surface: #ffffff;
  --color-surface-muted: #f7f7f9;
  --color-surface-subtle: #eeeef3;
  --color-border: #e0e0e8;
  --color-text-primary: #111118;
  --color-text-secondary: #555566;
  --color-text-muted: #888899;
  --color-text-on-dark: #ffffff;
  --color-deal-badge: #e94560;
  --color-deal-badge-text: #ffffff;
  --color-sale-price: #c73652;
  --color-original-price: #888899;
  --color-success: #1a7f4b;
  --color-focus-ring: #2563eb;

  --font-sans: "Inter", system-ui, -apple-system, sans-serif;
  --font-serif: "Georgia", "Times New Roman", serif;

  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,.10), 0 2px 6px rgba(0,0,0,.06);
  --shadow-lg: 0 12px 32px rgba(0,0,0,.12), 0 4px 12px rgba(0,0,0,.08);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;

  --container-max: 1280px;
  --container-padding: clamp(1rem, 4vw, 2.5rem);
}

/* ============================================================
   Reset & Base
   ============================================================ */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--color-surface);
  color: var(--color-text-primary);
  line-height: 1.6;
  min-width: 320px;
  -webkit-font-smoothing: antialiased;
}

img, svg { max-width: 100%; display: block; }

a { color: inherit; text-decoration: none; }

ul, ol { list-style: none; }

button { cursor: pointer; font: inherit; border: none; background: none; }

/* ============================================================
   Focus & Accessibility
   ============================================================ */
:focus-visible {
  outline: 3px solid var(--color-focus-ring);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 9999;
  padding: .6rem 1.2rem;
  background: var(--color-brand-primary);
  color: var(--color-text-on-dark);
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
  font-weight: 600;
  font-size: .9rem;
  transition: top var(--transition-fast);
}
.skip-link:focus { top: 0; }

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ============================================================
   Layout Helpers
   ============================================================ */
.container {
  max-width: var(--container-max);
  margin-inline: auto;
  padding-inline: var(--container-padding);
}

.section { padding-block: clamp(3rem, 7vw, 5.5rem); }
.section--muted { background: var(--color-surface-muted); }
.section--dark {
  background: var(--color-brand-primary);
  color: var(--color-text-on-dark);
}

.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: 2rem;
}

.section-title {
  font-size: clamp(1.4rem, 3vw, 2rem);
  font-weight: 700;
  letter-spacing: -.02em;
  line-height: 1.2;
}

.section-link {
  font-size: .875rem;
  font-weight: 600;
  color: var(--color-brand-accent);
  display: inline-flex;
  align-items: center;
  gap: .3rem;
  white-space: nowrap;
  transition: color var(--transition-fast);
}
.section-link:hover { color: var(--color-brand-accent-hover); text-decoration: underline; }
.section-link svg { flex-shrink: 0; }

/* ============================================================
   Buttons
   ============================================================ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .45rem;
  padding: .65rem 1.4rem;
  border-radius: var(--radius-full);
  font-size: .9rem;
  font-weight: 600;
  letter-spacing: .01em;
  transition: background var(--transition-fast), color var(--transition-fast),
              box-shadow var(--transition-fast), transform var(--transition-fast);
  white-space: nowrap;
}
.btn:active { transform: scale(.97); }

.btn--primary {
  background: var(--color-brand-accent);
  color: var(--color-text-on-dark);
}
.btn--primary:hover { background: var(--color-brand-accent-hover); box-shadow: var(--shadow-md); }

.btn--outline {
  background: transparent;
  color: var(--color-brand-primary);
  border: 2px solid currentColor;
}
.btn--outline:hover { background: var(--color-brand-primary); color: var(--color-text-on-dark); }

.btn--ghost {
  background: rgba(255,255,255,.15);
  color: var(--color-text-on-dark);
  border: 2px solid rgba(255,255,255,.4);
}
.btn--ghost:hover { background: rgba(255,255,255,.25); }

.btn--icon {
  padding: .6rem;
  border-radius: var(--radius-full);
  line-height: 1;
}

/* ============================================================
   Announcement Bar
   ============================================================ */
.announcement-bar {
  background: var(--color-brand-primary);
  color: var(--color-text-on-dark);
  text-align: center;
  padding: .55rem 1rem;
  font-size: .8rem;
  font-weight: 500;
  letter-spacing: .03em;
}
.announcement-bar a { text-decoration: underline; color: inherit; font-weight: 700; }
.announcement-bar a:hover { color: #ffd0da; }

/* ============================================================
   Header / Nav
   ============================================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
}

.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 1.5rem;
  height: 64px;
}

.site-logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--color-brand-primary);
  letter-spacing: -.03em;
  flex-shrink: 0;
}
.site-logo .logo-dot { color: var(--color-brand-accent); }

/* Primary nav */
.primary-nav { display: flex; align-items: center; justify-content: center; }
.nav-list {
  display: flex;
  gap: .25rem;
}
.nav-link {
  padding: .4rem .75rem;
  border-radius: var(--radius-sm);
  font-size: .875rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  transition: color var(--transition-fast), background var(--transition-fast);
}
.nav-link:hover { color: var(--color-text-primary); background: var(--color-surface-subtle); }
.nav-link[aria-current="page"] { color: var(--color-brand-accent); font-weight: 600; }

/* Header actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: .25rem;
}

.header-search {
  position: relative;
  display: flex;
  align-items: center;
}
.header-search input {
  width: 200px;
  padding: .45rem .9rem .45rem 2.3rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-full);
  font: inherit;
  font-size: .85rem;
  color: var(--color-text-primary);
  background: var(--color-surface-muted);
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast), width var(--transition-base);
}
.header-search input:focus {
  outline: none;
  border-color: var(--color-focus-ring);
  box-shadow: 0 0 0 3px rgba(37,99,235,.2);
  width: 240px;
}
.header-search input::placeholder { color: var(--color-text-muted); }
.search-icon {
  position: absolute;
  left: .65rem;
  color: var(--color-text-muted);
  pointer-events: none;
}

.cart-btn {
  position: relative;
  color: var(--color-text-primary);
  padding: .55rem;
  border-radius: var(--radius-full);
  transition: background var(--transition-fast);
}
.cart-btn:hover { background: var(--color-surface-subtle); }
.cart-count {
  position: absolute;
  top: 2px; right: 2px;
  width: 17px; height: 17px;
  background: var(--color-brand-accent);
  color: #fff;
  font-size: .65rem;
  font-weight: 700;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  pointer-events: none;
}

.mobile-menu-btn {
  display: none;
  padding: .55rem;
  border-radius: var(--radius-sm);
  color: var(--color-text-primary);
}

/* Mobile nav */
.mobile-nav {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 200;
  background: rgba(0,0,0,.5);
}
.mobile-nav[aria-hidden="false"] { display: block; }
.mobile-nav-panel {
  position: absolute;
  top: 0; right: 0;
  height: 100%;
  width: min(320px, 85vw);
  background: var(--color-surface);
  box-shadow: var(--shadow-lg);
  overflow-y: auto;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}
.mobile-nav-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.mobile-nav-list { display: flex; flex-direction: column; gap: .25rem; }
.mobile-nav-list .nav-link {
  display: block;
  padding: .6rem .75rem;
  font-size: 1rem;
}

/* ============================================================
   Hero
   ============================================================ */
.hero {
  background: var(--color-brand-primary);
  color: var(--color-text-on-dark);
  overflow: hidden;
  position: relative;
}

.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  align-items: center;
  min-height: 520px;
  padding-block: 4rem;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--color-brand-accent);
  background: rgba(233,69,96,.15);
  padding: .35rem .75rem;
  border-radius: var(--radius-full);
  margin-bottom: 1.25rem;
}

.hero-title {
  font-size: clamp(2.2rem, 5vw, 3.6rem);
  font-weight: 800;
  letter-spacing: -.04em;
  line-height: 1.08;
  margin-bottom: 1.25rem;
}
.hero-title .accent { color: var(--color-brand-accent); }

.hero-desc {
  font-size: clamp(.95rem, 2vw, 1.1rem);
  color: rgba(255,255,255,.75);
  line-height: 1.7;
  max-width: 44ch;
  margin-bottom: 2rem;
}

.hero-cta-group {
  display: flex;
  gap: .75rem;
  flex-wrap: wrap;
}

.hero-stats {
  display: flex;
  gap: 2rem;
  margin-top: 2.5rem;
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,.12);
}
.hero-stat-value {
  font-size: 1.6rem;
  font-weight: 800;
  letter-spacing: -.03em;
  line-height: 1;
}
.hero-stat-label {
  font-size: .75rem;
  color: rgba(255,255,255,.6);
  margin-top: .2rem;
}

.hero-visual {
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.hero-image-placeholder {
  width: 100%;
  max-width: 480px;
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, rgba(255,255,255,.08) 0%, rgba(233,69,96,.2) 100%);
  border-radius: var(--radius-lg);
  border: 1px solid rgba(255,255,255,.1);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 1rem;
  color: rgba(255,255,255,.4);
  font-size: .85rem;
  position: relative;
  overflow: hidden;
}
.hero-image-placeholder::before {
  content: '';
  position: absolute;
  width: 200px; height: 200px;
  background: rgba(233,69,96,.3);
  border-radius: 50%;
  top: -40px; right: -40px;
  filter: blur(60px);
}
.hero-badge {
  position: absolute;
  bottom: 1.5rem;
  left: 1.5rem;
  background: var(--color-surface);
  color: var(--color-text-primary);
  border-radius: var(--radius-md);
  padding: .75rem 1rem;
  box-shadow: var(--shadow-lg);
  display: flex;
  align-items: center;
  gap: .6rem;
  font-size: .8rem;
}
.hero-badge-icon {
  width: 36px; height: 36px;
  background: #fff0f3;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-brand-accent);
  flex-shrink: 0;
}
.hero-badge strong { display: block; font-size: .85rem; }
.hero-badge span { color: var(--color-text-muted); }

/* ============================================================
   Category Strip
   ============================================================ */
.category-strip { padding-block: 2.5rem; }
.category-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 1rem;
}
.category-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .6rem;
  padding: 1.25rem .75rem;
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  text-align: center;
  font-size: .8rem;
  font-weight: 600;
  color: var(--color-text-secondary);
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast),
              color var(--transition-fast), transform var(--transition-fast);
  cursor: pointer;
}
.category-card:hover {
  border-color: var(--color-brand-accent);
  box-shadow: var(--shadow-sm);
  color: var(--color-brand-accent);
  transform: translateY(-2px);
}
.category-icon {
  width: 44px; height: 44px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
}

/* ============================================================
   Product Card
   ============================================================ */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1.5rem;
}

.product-card {
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition-base), transform var(--transition-base),
              border-color var(--transition-fast);
}
.product-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
  border-color: #c8c8d8;
}

.product-image-wrap {
  position: relative;
  background: var(--color-surface-muted);
  aspect-ratio: 4/3;
  overflow: hidden;
}
.product-image-placeholder {
  width: 100%; height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  user-select: none;
  transition: transform var(--transition-base);
}
.product-card:hover .product-image-placeholder { transform: scale(1.05); }

.product-badge {
  position: absolute;
  top: .6rem;
  left: .6rem;
  padding: .25rem .6rem;
  border-radius: var(--radius-full);
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
  pointer-events: none;
}
.product-badge--sale { background: var(--color-deal-badge); color: var(--color-deal-badge-text); }
.product-badge--new { background: var(--color-brand-primary); color: #fff; }
.product-badge--trending { background: #7c3aed; color: #fff; }

.product-wishlist {
  position: absolute;
  top: .6rem;
  right: .6rem;
  width: 32px; height: 32px;
  background: var(--color-surface);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-sm);
  color: var(--color-text-muted);
  transition: color var(--transition-fast), box-shadow var(--transition-fast);
  opacity: 0;
  transition: opacity var(--transition-fast), color var(--transition-fast);
}
.product-card:hover .product-wishlist,
.product-wishlist:focus-visible { opacity: 1; }
.product-wishlist[aria-pressed="true"] { color: var(--color-brand-accent); opacity: 1; }
.product-wishlist:hover { color: var(--color-brand-accent); box-shadow: var(--shadow-md); }

.product-info { padding: 1rem; flex: 1; display: flex; flex-direction: column; gap: .4rem; }

.product-brand {
  font-size: .7rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--color-text-muted);
}
.product-name {
  font-size: .95rem;
  font-weight: 600;
  line-height: 1.35;
  color: var(--color-text-primary);
}

.product-rating {
  display: flex;
  align-items: center;
  gap: .3rem;
}
.stars { color: #f59e0b; font-size: .8rem; line-height: 1; letter-spacing: -.05em; }
.rating-count { font-size: .75rem; color: var(--color-text-muted); }

.product-price-row {
  display: flex;
  align-items: center;
  gap: .5rem;
  margin-top: auto;
  padding-top: .5rem;
}
.price-current {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--color-text-primary);
}
.price-current--sale { color: var(--color-sale-price); }
.price-original {
  font-size: .85rem;
  color: var(--color-original-price);
  text-decoration: line-through;
}
.price-save {
  font-size: .7rem;
  font-weight: 700;
  background: #fef2f2;
  color: var(--color-sale-price);
  padding: .15rem .4rem;
  border-radius: var(--radius-full);
}

.product-add-btn {
  margin: 0 1rem 1rem;
  width: calc(100% - 2rem);
  padding: .6rem 1rem;
  background: var(--color-brand-primary);
  color: var(--color-text-on-dark);
  border-radius: var(--radius-full);
  font-size: .85rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .4rem;
  transition: background var(--transition-fast), box-shadow var(--transition-fast);
}
.product-add-btn:hover { background: var(--color-brand-accent); box-shadow: var(--shadow-sm); }
.product-add-btn:focus-visible {
  outline: 3px solid var(--color-focus-ring);
  outline-offset: 3px;
}

/* ============================================================
   Deals Banner
   ============================================================ */
.deals-section { overflow: hidden; }

.deals-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 1.5rem;
}

.deal-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  min-height: 340px;
  padding: 2rem;
}

.deal-card--primary {
  background: linear-gradient(145deg, #1a1a2e 0%, #2d1b56 100%);
  color: var(--color-text-on-dark);
}
.deal-card--secondary {
  background: linear-gradient(145deg, #0f3460 0%, #16213e 100%);
  color: var(--color-text-on-dark);
}

.deal-card-bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}
.deal-card-bg::before {
  content: '';
  position: absolute;
  width: 280px; height: 280px;
  border-radius: 50%;
  opacity: .5;
}
.deal-card--primary .deal-card-bg::before {
  background: radial-gradient(circle, rgba(233,69,96,.4) 0%, transparent 70%);
  top: -80px; right: -60px;
}
.deal-card--secondary .deal-card-bg::before {
  background: radial-gradient(circle, rgba(99,179,237,.3) 0%, transparent 70%);
  top: -40px; left: -40px;
}

.deal-emoji {
  font-size: 4rem;
  position: absolute;
  top: 1.5rem; right: 2rem;
  filter: drop-shadow(0 4px 12px rgba(0,0,0,.3));
  line-height: 1;
}

.deal-eyebrow {
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  opacity: .7;
  margin-bottom: .5rem;
}
.deal-title {
  font-size: clamp(1.4rem, 2.5vw, 2rem);
  font-weight: 800;
  letter-spacing: -.03em;
  line-height: 1.15;
  margin-bottom: .5rem;
}
.deal-desc { font-size: .875rem; opacity: .75; margin-bottom: 1.25rem; line-height: 1.55; }

.deal-countdown {
  display: flex;
  gap: .5rem;
  margin-bottom: 1.25rem;
}
.countdown-unit {
  text-align: center;
  background: rgba(255,255,255,.12);
  border-radius: var(--radius-sm);
  padding: .4rem .6rem;
  min-width: 48px;
}
.countdown-num {
  font-size: 1.25rem;
  font-weight: 800;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.countdown-label { font-size: .6rem; opacity: .65; letter-spacing: .06em; text-transform: uppercase; }

/* ============================================================
   Deals — horizontal scroll list
   ============================================================ */
.deals-list-section { padding-block: 3rem; }

.deals-scroll-container {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: var(--color-border) transparent;
  padding-bottom: .75rem;
  margin-inline: calc(-1 * var(--container-padding));
  padding-inline: var(--container-padding);
}

.deals-scroll-inner {
  display: flex;
  gap: 1.25rem;
  width: max-content;
}

.deal-product-card {
  width: 200px;
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  flex-shrink: 0;
  transition: box-shadow var(--transition-base), transform var(--transition-base);
}
.deal-product-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}

.deal-product-image {
  background: var(--color-surface-muted);
  aspect-ratio: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.8rem;
  position: relative;
}
.deal-product-discount {
  position: absolute;
  top: .5rem; left: .5rem;
  background: var(--color-brand-accent);
  color: #fff;
  font-size: .7rem;
  font-weight: 700;
  padding: .2rem .45rem;
  border-radius: var(--radius-full);
}

.deal-product-info { padding: .75rem; }
.deal-product-name { font-size: .8rem; font-weight: 600; line-height: 1.35; margin-bottom: .4rem; }
.deal-product-price { display: flex; align-items: center; gap: .4rem; flex-wrap: wrap; }
.deal-product-price .price-current { font-size: .95rem; }

.deals-progress { margin-top: .5rem; }
.deals-progress-bar-wrap {
  height: 6px;
  background: var(--color-surface-subtle);
  border-radius: var(--radius-full);
  overflow: hidden;
  margin-bottom: .3rem;
}
.deals-progress-bar {
  height: 100%;
  background: var(--color-brand-accent);
  border-radius: var(--radius-full);
  transition: width 1s ease;
}
.deals-progress-label { font-size: .7rem; color: var(--color-text-muted); }

/* ============================================================
   Editorial / Content Section
   ============================================================ */
.editorial-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  gap: 1.5rem;
  align-items: start;
}

.editorial-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  transition: box-shadow var(--transition-base), transform var(--transition-base);
}
.editorial-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }

.editorial-card-image {
  background: var(--color-surface-muted);
  aspect-ratio: 16/9;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3.5rem;
  overflow: hidden;
  transition: transform var(--transition-base);
}
.editorial-card:hover .editorial-card-image { transform: scale(1.02); }

.editorial-card-image--tall { aspect-ratio: 4/5; }

.editorial-card-body { padding: 1.25rem; }

.editorial-tag {
  display: inline-block;
  font-size: .7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .08em;
  color: var(--color-brand-accent);
  margin-bottom: .5rem;
}

.editorial-title {
  font-size: clamp(1rem, 2vw, 1.2rem);
  font-weight: 700;
  line-height: 1.3;
  letter-spacing: -.01em;
  margin-bottom: .5rem;
}

.editorial-excerpt {
  font-size: .85rem;
  color: var(--color-text-secondary);
  line-height: 1.6;
  margin-bottom: 1rem;
}

.editorial-meta {
  display: flex;
  align-items: center;
  gap: .75rem;
  font-size: .75rem;
  color: var(--color-text-muted);
}
.editorial-meta-dot { color: var(--color-border); }

.editorial-side { display: flex; flex-direction: column; gap: 1.5rem; }

/* Small editorial card */
.editorial-card--small { display: flex; gap: 1rem; border-radius: var(--radius-md); }
.editorial-card--small .editorial-card-image {
  width: 100px;
  flex-shrink: 0;
  aspect-ratio: 1;
  border-radius: var(--radius-sm) 0 0 var(--radius-sm);
  font-size: 2rem;
}
.editorial-card--small .editorial-card-body { padding: .75rem .75rem .75rem 0; }
.editorial-card--small .editorial-title { font-size: .9rem; }
.editorial-card--small .editorial-excerpt { display: none; }

/* ============================================================
   Value Props / Trust Bar
   ============================================================ */
.trust-bar { border-top: 1px solid var(--color-border); border-bottom: 1px solid var(--color-border); padding-block: 2rem; }
.trust-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 1.5rem;
}
.trust-item {
  display: flex;
  align-items: center;
  gap: .75rem;
}
.trust-icon {
  width: 44px; height: 44px;
  background: #fff0f3;
  color: var(--color-brand-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.trust-text strong { display: block; font-size: .875rem; font-weight: 700; }
.trust-text span { font-size: .78rem; color: var(--color-text-muted); }

/* ============================================================
   Newsletter
   ============================================================ */
.newsletter {
  background: linear-gradient(135deg, var(--color-brand-primary) 0%, #2d1b56 100%);
  color: var(--color-text-on-dark);
  text-align: center;
  padding-block: clamp(3rem, 7vw, 5rem);
}
.newsletter-inner { max-width: 560px; margin-inline: auto; }
.newsletter-eyebrow {
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--color-brand-accent);
  margin-bottom: .75rem;
}
.newsletter-title {
  font-size: clamp(1.6rem, 4vw, 2.4rem);
  font-weight: 800;
  letter-spacing: -.03em;
  line-height: 1.15;
  margin-bottom: .75rem;
}
.newsletter-desc {
  font-size: .95rem;
  color: rgba(255,255,255,.7);
  margin-bottom: 2rem;
  line-height: 1.6;
}
.newsletter-form { display: flex; gap: .75rem; flex-wrap: wrap; justify-content: center; }
.newsletter-input-wrap { flex: 1; min-width: 240px; position: relative; }
.newsletter-input-label {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
}
.newsletter-input {
  width: 100%;
  padding: .8rem 1.2rem;
  border-radius: var(--radius-full);
  border: 2px solid rgba(255,255,255,.2);
  background: rgba(255,255,255,.1);
  color: var(--color-text-on-dark);
  font: inherit;
  font-size: .9rem;
  transition: border-color var(--transition-fast), background var(--transition-fast);
}
.newsletter-input::placeholder { color: rgba(255,255,255,.45); }
.newsletter-input:focus {
  outline: none;
  border-color: var(--color-focus-ring);
  box-shadow: 0 0 0 3px rgba(37,99,235,.35);
  background: rgba(255,255,255,.15);
}
.newsletter-success {
  display: none;
  align-items: center;
  gap: .5rem;
  font-weight: 600;
  color: #86efac;
  justify-content: center;
  margin-top: 1rem;
}
.newsletter-success[aria-live] { }

/* ============================================================
   Footer
   ============================================================ */
.site-footer {
  background: var(--color-brand-primary);
  color: rgba(255,255,255,.75);
  padding-top: 3.5rem;
  padding-bottom: 2rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(3, 1fr);
  gap: 2.5rem;
  margin-bottom: 3rem;
}
.footer-brand .site-logo { color: var(--color-text-on-dark); margin-bottom: .75rem; }
.footer-brand p { font-size: .85rem; line-height: 1.65; max-width: 30ch; }

.footer-col-title {
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: rgba(255,255,255,.45);
  margin-bottom: 1rem;
}
.footer-links { display: flex; flex-direction: column; gap: .5rem; }
.footer-links a {
  font-size: .875rem;
  color: rgba(255,255,255,.65);
  transition: color var(--transition-fast);
  display: inline-flex;
  align-items: center;
  gap: .3rem;
}
.footer-links a:hover { color: #fff; text-decoration: underline; }

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,.1);
  font-size: .78rem;
}
.footer-legal { display: flex; gap: 1.25rem; }
.footer-legal a { color: rgba(255,255,255,.5); }
.footer-legal a:hover { color: #fff; text-decoration: underline; }

.social-links { display: flex; gap: .5rem; }
.social-link {
  width: 34px; height: 34px;
  border: 1px solid rgba(255,255,255,.2);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,.6);
  font-size: .8rem;
  transition: background var(--transition-fast), color var(--transition-fast), border-color var(--transition-fast);
}
.social-link:hover { background: rgba(255,255,255,.1); color: #fff; border-color: rgba(255,255,255,.5); }

/* ============================================================
   Toast / Cart feedback
   ============================================================ */
.toast-container {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  z-index: 999;
  display: flex;
  flex-direction: column;
  gap: .5rem;
  pointer-events: none;
}
.toast {
  background: var(--color-brand-primary);
  color: #fff;
  padding: .75rem 1.25rem;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  font-size: .875rem;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: .5rem;
  opacity: 0;
  transform: translateY(8px);
  transition: opacity .25s ease, transform .25s ease;
  pointer-events: auto;
  max-width: 320px;
}
.toast.show { opacity: 1; transform: translateY(0); }
.toast-icon { color: #86efac; font-size: 1rem; flex-shrink: 0; }

/* ============================================================
   Responsive
   ============================================================ */
@media (max-width: 900px) {
  .hero-inner { grid-template-columns: 1fr; min-height: unset; padding-block: 3rem; }
  .hero-visual { display: none; }
  .hero-stats { gap: 1.5rem; }
  .deals-grid { grid-template-columns: 1fr; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card--small { flex-direction: column; }
  .editorial-card--small .editorial-card-image { width: 100%; aspect-ratio: 16/9; border-radius: var(--radius-sm) var(--radius-sm) 0 0; }
  .editorial-card--small .editorial-card-body { padding: .75rem; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .footer-brand { grid-column: span 2; }
}

@media (max-width: 680px) {
  .primary-nav { display: none; }
  .mobile-menu-btn { display: flex; align-items: center; justify-content: center; }
  .header-search input { width: 160px; }
  .header-search input:focus { width: 180px; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-brand { grid-column: span 1; }
  .product-grid { grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); }
}

@media (max-width: 400px) {
  .hero-stats { flex-direction: column; gap: 1rem; }
  .hero-cta-group .btn:last-child { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .01ms !important;
    transition-duration: .01ms !important;
  }
}

@media (forced-colors: active) {
  .product-badge, .deal-badge, .cart-count { forced-color-adjust: none; }
  .btn--primary { background: ButtonText; color: ButtonFace; border: 2px solid ButtonBorder; }
  .site-header { border-bottom: 1px solid ButtonBorder; }
  .product-card, .deal-product-card, .editorial-card, .category-card { border: 1px solid ButtonBorder; }
  .trust-icon, .hero-badge-icon { background: Canvas; color: ButtonText; border: 1px solid ButtonBorder; }
}
